#!/usr/bin/env python3
"""Write SYNTHETIC nccl-tests-style tables from the ring alpha-beta model of module perf-models (not measurements).

T(n) = 2(p-1)*alpha + 2(p-1)/p * n / B   with +-1.5 % seeded noise; busbw = algbw * 2(p-1)/p (PERFORMANCE.md of nccl-tests).
"""
from __future__ import annotations

import random
from pathlib import Path

HERE = Path(__file__).parent / "fixtures"


def table(p: int, alpha_us: float, B_gbs: float, seed: int, wrong_at: int | None = None) -> str:
    rng = random.Random(seed)
    out = [
        "# SYNTHETIC output generated by make_sample.py from a ring alpha-beta model; it was NOT produced by nccl-tests on a GPU.",
        "# nccl-tests version (synthetic) nccl-headers=0 nccl-library=0",
        "# Collective test starting: all_reduce_perf",
        "# nThread 1 nGpus 1 minBytes 8 maxBytes 17179869184 step: 2(factor) warmup iters: 1 iters: 20 agg iters: 1 validation: 1 graph: 0",
        "#",
        "# Using devices",
    ]
    out += [f"#  Rank {r:2d} Group  0 Pid {5000 + r} on node-{r // 8 + 1:02d} device {r % 8:2d} [0x{0x1b + r % 8:02x}] synthetic-gpu" for r in range(p)]
    out += [
        "#",
        "#                                                              out-of-place                       in-place",
        "#       size         count      type   redop    root     time   algbw   busbw  #wrong     time   algbw   busbw  #wrong",
        "#        (B)    (elements)                               (us)  (GB/s)  (GB/s)             (us)  (GB/s)  (GB/s)",
    ]
    f = 2 * (p - 1) / p
    size, bws = 8, []
    while size <= 1 << 34:
        cols = []
        for _ in range(2):
            t = (2 * (p - 1) * alpha_us * 1e-6 + f * size / (B_gbs * 1e9)) * (1 + rng.uniform(-0.015, 0.015))
            alg = size / t / 1e9
            cols.append((t * 1e6, alg, alg * f))
        wrong = 7 if wrong_at == size else 0
        row = f"{size:12d} {size // 4:12d} {'float':>8} {'sum':>6} {-1:6d}"
        for i, (t, a, b) in enumerate(cols):
            row += f" {t:7.1f} {a:6.2f} {b:6.2f} {wrong if i == 0 else 0:6d}"
        out.append(row)
        bws.append(max(cols[0][2], cols[1][2]))
        size *= 2
    out += ["# Out of bounds values : %d %s" % (1 if wrong_at else 0, "FAILED" if wrong_at else "OK"), "# Avg bus bandwidth    : %g " % round(sum(bws) / len(bws), 5), "#", "# Collective test concluded: all_reduce_perf"]
    return "\n".join(out) + "\n"


def main() -> None:
    HERE.mkdir(exist_ok=True)
    (HERE / "all_reduce_synthetic_ok.txt").write_text(table(16, 12.0, 48.0, 1), encoding="utf-8")
    (HERE / "all_reduce_synthetic_degraded.txt").write_text(table(16, 12.0, 26.0, 2), encoding="utf-8")
    (HERE / "all_reduce_synthetic_wrong.txt").write_text(table(16, 12.0, 48.0, 3, wrong_at=1 << 20), encoding="utf-8")
    print("wrote 3 fixtures")


if __name__ == "__main__":
    main()
